options(stringsAsFactors=FALSE)
stopifnot(getRversion()=="4.6.1")
root <- normalizePath(getwd())
out <- file.path(root,"audit/manuscript_nature_health/revision_2026_09_11/consolidated_display_repair_order72k/environment_recovery_001")
base <- file.path(root,"audit/report_harmonization/report018_order72k_environment_cache_recovery_001")
sha <- function(p) {c <- file(p,"rb");on.exit(close(c));unname(unclass(as.character(openssl::sha256(c))))}
resolve <- function(p) normalizePath(if(startsWith(p,"/")) p else file.path(root,p),mustWork=TRUE)
pins <- c(environment_input_pins="d109efc0ed9b6169f4786475da448d360b45a99617ac79cf18e64619cb33aefd",release_manifest="87f2c204e95fb05c8faab14dfca06ea65c8d13040fc65edd497a2637282ad471",dispatch_manifest="50f83361597d370b5eeab89f53c55cd8f8467d7cb1009a2f56568b576765bfae")
all <- list()
for(k in names(pins)) {
  p <- file.path(base,paste0(k,".csv"));stopifnot(sha(p)==pins[[k]])
  x <- read.csv(p);paths <- vapply(x$path,resolve,character(1));actual <- vapply(paths,sha,character(1))
  all[[k]] <- data.frame(inventory=k,path=x$path,sha256=actual,hash_exact=actual==x$sha256,size_exact=file.info(paths)$size==x$bytes)
}
x <- do.call(rbind,all)
stopifnot(nrow(x)==380L,all(x$hash_exact),all(x$size_exact))
write.csv(x,file.path(out,"preflight_380_identities.csv"),row.names=FALSE)
original <- c("audit/report_harmonization/report018_order72k_non_s5_integration_release/release_manifest.csv","audit/report_harmonization/report018_order72k_non_s5_integration_release/integration_input_pins.csv","audit/report_harmonization/report018_order72k_non_s5_integration_dispatch/dependency_closure_pins.csv")
rows <- lapply(original,function(p){d<-read.csv(resolve(p));files<-vapply(d$path,resolve,character(1));actual<-vapply(files,sha,character(1));data.frame(inventory=p,path=d$path,sha256=actual,hash_exact=actual==d$sha256,size_exact=file.info(files)$size==d$bytes)})
y <- do.call(rbind,rows);stopifnot(nrow(y)==423L,all(y$hash_exact),all(y$size_exact))
write.csv(y,file.path(out,"original_authority_rehash.csv"),row.names=FALSE)
runtime <- read.csv(file.path(base,"runtime_pins.csv"));rp <- vapply(runtime$path,resolve,character(1));stopifnot(all(vapply(rp,sha,character(1))==runtime$sha256))
tmp <- "/private/tmp/order72k_3ok569jd";stopifnot(dir.exists(tmp),Sys.readlink(tmp)=="")
selection <- file.path(root,"audit/manuscript_nature_health/consolidated_display_repair_2026_09_11/integration_candidate_order72k/project")
stopifnot(!length(list.files(file.path(selection,"render_attempt1"),pattern="\\.html$",recursive=TRUE)))
writeLines(c("PASS: 380 recovery rows, 423 original authority members, four runtime pins, task scratch nonsymlink, no HTML to overwrite.",capture.output(sessionInfo())),file.path(out,"preflight_session.txt"))
cat("PASS 380 recovery rows; 423 original members; runtime exact; no HTML to overwrite.\n")
